import * as React from "react";
import  { useState } from 'react';
import "./Avatar.scss";
import { MenuBlock } from "../menuBlock";
import { MpaIcon } from "../icon/MpaIcon";
import {SvgMpaIcon} from "../../assets/icons/index";

export interface AvatarProps {
  /**
   * Unique identifier for the avatar component
   */
  id: string;
  /**
   * Hex code that determines the background colour.
   */
  colour?: "coloured" | "neutral" | "white-fill";
  /**
   * Determines the type of the avatar.
   */
  type?: "icon" | "image" | "monogram";  
  /**
   * Determines the size of the avatar small (32) | medium (40) | large (48).
   */
  size?: "small" | "medium" | "large";  
  /**
   * Custom onClick function that can be passed to the element for customizing behavior.
   */
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  /**
   * Username for generating a monogram (only needed for type="monogram").
   */
  username?: string;

  /**
   * URL of the image to be displayed in the avatar.
   * Required when `type="image"`.
  */
  imageUrl?: string;

  /**
   * Icon name from `SvgMpaIcon` or a custom string icon.
   * Used when `type="icon"`.
   */
  icon?: keyof typeof SvgMpaIcon | string;

  /**
   * Define the menu block position
   */
  position?: "left" | "right";
  /**
   * Determine show/ hide the menu block
   */
  showMenuBlock?:  boolean;

  /**
   * Menu items to display in the dropdown menu when the avatar is clicked.
   * If not provided or empty, no menu is shown.
   */
  menuItems?: MenuItem[];

}


export interface MenuItem {
  label: string;
  link: string;
  leadingIcon?: React.ReactNode;
}

export const Avatar: React.FC<AvatarProps> = ({
    id,
    colour = "neutral",
    type,
    size = "small",
    // onClick,
    username,
    imageUrl,
    icon = "User",
    position,
    menuItems = [],
    showMenuBlock=true
}) => {

  let sizeClass = ["small", "medium", "large"].includes(size)
  ? ` ${size}`
  : " small";

  let avatarClassName = [
    "mpa-avatar",
    type || "icon",
    sizeClass,
    colour || "neutral"
  ].filter(Boolean).join(" ");


  
  const getIconSize = (size: AvatarProps["size"]): string => {
      const map: Record<NonNullable<AvatarProps["size"]>, string> = {
        "small": "20",
        "medium": "24",
        "large": "32"
      };
      return map[(size || "medium") as NonNullable<AvatarProps["size"]>];
  };
  
  const iconSize = getIconSize(size);

  let avatarContent;
  if (type === "icon") {
      avatarContent = <MpaIcon iconName={icon} size={iconSize} />; 
  } else if (type === "image") {
      avatarContent = <img src={imageUrl} alt="avatar" />;
  } else if (type === "monogram" && username) {
    const names = username.trim().split(/\s+/);
    let initials = "";
    if (names.length === 1) {
      // Case: "John" -> "J"
      initials = names[0].charAt(0).toUpperCase();
    } else {
      // Case: "John Smith" -> "JS" 
      // Case: "John Smith Killa" -> "JK"
      const firstInitial = names[0].charAt(0).toUpperCase();
      const lastInitial = names[names.length - 1].charAt(0).toUpperCase();
      initials = firstInitial + lastInitial;
    }

    avatarContent = <span className="monogram">{initials}</span>;
  }

  const [menuBlock, setMenuBlock] = useState(false);
  const handleShowMenuBlock  = (e: React.MouseEvent<HTMLSpanElement> | React.KeyboardEvent<HTMLSpanElement>) => {
    if ((e.target as HTMLElement).closest(".menu-block")) {
      return;
    }
    setMenuBlock((prev) => !prev);
  };
    
  const validMenuItems = Array.isArray(menuItems) ? menuItems : [];

  return (
    <div id={id} className="avatar-wrapper">
      <span
          className={avatarClassName}
          onClick={handleShowMenuBlock}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault(); 
              handleShowMenuBlock(e);
            }
          }}
          role="button"
          tabIndex={0}
        >
        {avatarContent}
      </span>

      {menuBlock && validMenuItems.length > 0 && showMenuBlock && (
        <div className={`menu-block-wrapper position-${position || "right"}`}>
          <MenuBlock id={"menuBlockId"} menuItems={validMenuItems} colour={"primary"}/>
        </div>
      )}
    </div>
  );

};

export default Avatar;
